def family_json(row: tuple) -> dict:
    fid, ru, en, area, aliases, subtypes, skills, _ = row
    return {"id": fid, "name_ru": ru, "name_en": en, "parent_area": area, "aliases": aliases, "subtypes": subtypes,
            "skills": [{"id": key, "label": label} for key, label in skills], "data_mode": "synthetic"}

def month_shift(year: int, month: int, delta: int) -> tuple[int, int]:
    total = year * 12 + month - 1 + delta
    return total // 12, total % 12 + 1

def month_text(value: tuple[int, int]) -> str:
    return f"{value[0]:04d}-{value[1]:02d}"

def sentence_start(text: str) -> str:
    return text[:1].upper() + text[1:]

def build_history(index: int, row: tuple, level: str, total_months: int, path: int) -> list[dict]:
    if total_months < 8 or index % 13 == 0:
        return []
    count = min(3, 1 + int(index % 3 == 0) + int(index % 7 == 0), max(1, total_months // 6))
    base, remainder = divmod(total_months, count)
    durations = [base + int(i < remainder) for i in range(count)]
    end = (2026, 9)
    output = []
    for part, duration in enumerate(reversed(durations)):
        start = month_shift(*end, -duration + 1)
        ctx, act, result = row[7][(index + part + path) % 3]
        output.append({"title": CAREER_TITLES[level][(index + part) % 3],
                       "organization": f"Демо-команда {row[0].replace('_','-')}-{(index + part) % 9 + 1:02d}",
                       "period": {"from": month_text(start), "to": month_text(end)},
                       "employment_type": ("full_time", "project", "part_time")[(index + part + path) % 3],
                       "work_summary": sentence_start(ctx) + ".", "declared_actions": [act, f"Проверил результат на ограниченном сценарии: {result}."],
                       "result": result, "result_scope": ("individual", "team")[(index + part) % 2],
                       "provenance": "synthetic_candidate_claim", "verification_status": "not_assessed"})
        end = month_shift(*start, -1)
    return list(reversed(output))

def build_profile(global_id: int, row: tuple, local_index: int, rng: random.Random) -> dict:
    fid, ru, _, _, aliases, subtypes, skills, scenarios = row
    level = LEVELS[(global_id - 1) % 4]
    # Experience is varied independently of the self-declared level; it is never
    # used as a grade classifier. The overlapping ranges intentionally include
    # unconventional but plausible trajectories.
    experience_pool = {"junior": (0, 8, 14, 20, 26, 33, 38), "middle": (16, 24, 33, 42, 54, 66, 78, 90), "senior": (30, 42, 54, 72, 88, 104, 124, 144), "lead": (24, 36, 48, 60, 84, 108, 132, 156)}
    months = rng.choice(experience_pool[level])
    path_index = (global_id * 3 + local_index) % len(PATHS)
    scenario = scenarios[(local_index + global_id) % len(scenarios)]
    context, action, outcome = scenario
    subtype = subtypes[(local_index + global_id) % len(subtypes)]
    skill_start = (global_id + local_index) % len(skills)
    chosen_skills = [skills[(skill_start + step * 2) % len(skills)] for step in range(3)]
    focus = ", ".join(label for _, label in chosen_skills[:2])
    summary = SUMMARY_STYLES[global_id % len(SUMMARY_STYLES)].format(skills=focus)
    note = NARRATIVE_NOTES[local_index % len(NARRATIVE_NOTES)]
    result_scope = ("team", "individual")[(global_id + local_index) % 2]
    scope_prefix = "Заявленный командный результат:" if result_scope == "team" else "Заявленный личный результат:"
    story = {"context": f"В одном из синтетических проектов {context}. Это создавало риск для направления «{subtype}» и усложняло проверку результата. {note}",
             "personal_contribution": f"Мой вклад: {action}. Я согласовал границы изменения и оставил сценарий, который можно повторить.",
             "decision": DECISION_STYLES[(global_id + local_index) % len(DECISION_STYLES)].format(context=context),
             "outcome": f"{scope_prefix} {outcome}. Это вымышленный пример, не измерение реального проекта.",
             "result_scope": result_scope,
             "basis": "Со слов синтетического персонажа; подтверждающие материалы отсутствуют.", "verification_status": "not_assessed", "data_mode": "synthetic"}
    metric = None
    if global_id % 3 == 0:
        metric_label, metric_value = ILLUSTRATIVE_METRICS[(global_id + local_index) % len(ILLUSTRATIVE_METRICS)]
        metric = {"label": metric_label, "value": metric_value, "source": "synthetic_fixture",
                  "notice": "Число придумано для демонстрационного сценария и не является реальным измерением."}
        story["outcome"] += f" Условная иллюстрация: «{metric_label}» — {metric_value}; это не реальные данные."
    story["illustrative_metric"] = metric
    story["metric_notice"] = "Любые числа в этой истории придуманы и не подтверждают реальный результат." if metric else None
    history = build_history(local_index + global_id, row, level, months, path_index)
    project_count = (global_id + local_index) % 4
    projects = []
    for n in range(project_count):
        project_scenario = scenarios[(global_id + n + 1) % len(scenarios)]
        projects.append({"title": f"Практический проект {fid.replace('_',' ')} {global_id:03d}-{n+1}",
                         "kind": ("personal", "team", "coursework", "prototype")[(global_id + n) % 4],
                         "problem": sentence_start(project_scenario[0]) + ".", "my_role": CAREER_TITLES[level][(global_id + n) % 3],
                         "actions": [project_scenario[1], project_scenario[2]],
                         "stack": [skills[(global_id + n + j) % len(skills)][1] for j in range(2 + n % 2)],
                         "result": "Проверялось на демонстрационном сценарии; промышленное использование не заявляется.",
                         "provenance": "synthetic_fixture", "verification_status": "not_assessed"})
    education_status = "unknown" if global_id % 4 == 0 else "provided"
    education = [] if education_status == "unknown" else [{"institution": f"Вымышленная учебная площадка Демо-{global_id % 12 + 1:02d}",
        "program": ("Прикладная информатика", "Информационные системы", "Инженерная практика", "Самостоятельная программа")[(global_id + local_index) % 4],
        "period": f"{2012 + global_id % 12}–{2014 + global_id % 12}", "completion": ("completed", "in_progress", "coursework")[(global_id + 1) % 3], "provenance": "synthetic_fixture"}]
    language_status = "unknown" if global_id % 7 == 0 else "provided"
    languages = [] if language_status == "unknown" else [{"language": "Русский", "level": "native_or_fluent", "provenance": "synthetic_fixture"},
        {"language": "Английский", "level": ("A2", "B1", "B2", "C1")[(global_id + local_index) % 4], "provenance": "synthetic_fixture"}]
    cert_status = "unknown" if global_id % 3 else "provided"
    certificates = [] if cert_status == "unknown" else [{"name": f"Учебный модуль по направлению {ru}", "issuer": "Вымышленная учебная площадка",
        "issued_year": 2021 + global_id % 5, "credential_status": "training_record_not_verified", "provenance": "synthetic_fixture"}]
    return {"profile_id": f"syn-candidate-{global_id:03d}", "display_name": f"Кандидат S-{global_id:03d}",
        "resume_title": f"{subtype} · {LEVEL_LABELS[level]}", "data_mode": "synthetic", "origin": "synthetic_fixture", "assessment_status": "not_assessed",
        "target_roles": [{"role_family_id": fid, "role_family_name": ru, "subtype": subtype, "declared_level": level,
                          "level_note": "Уровень указан самим кандидатом; стаж не используется для его вывода.", "aliases": aliases[:2]}],
        "city": CITIES[(global_id * 3 + local_index) % len(CITIES)],
        "preferred_work_formats": [FORMATS[(global_id + local_index) % 3], FORMATS[(global_id + local_index + 1) % 3]],
        "salary_expectation_rub_month": None if global_id % 9 == 0 else {"min": 90000 + global_id % 6 * 18000, "max": 210000 + global_id % 7 * 24000, "basis": "synthetic_demo_range_not_market_data"},
        "experience_months_declared": months, "career_path": {"type": PATH_IDS[path_index], "description": PATHS[path_index]},
        "summary": summary, "skills": [{"id": key, "label": label, "source": "candidate_self_report", "verification_status": "not_assessed"} for key, label in chosen_skills],
        "work_history": history, "projects": projects, "education": education, "languages": languages, "certificates": certificates,
        "achievement_story": story,
        "section_status": {"education": education_status, "languages": language_status, "certificates": cert_status,
                           "work_history": "provided" if history else "unknown", "projects": "provided" if projects else "unknown"},
        "employer_sharing": {"enabled": global_id % 5 != 0, "scope": "resume_evidence_only", "explicit_opt_in_required": True},
        "contact": None, "privacy_note": "Синтетическая запись; контактные данные отсутствуют."}

def build_vacancy(global_id: int, row: tuple, family_index: int, local_index: int) -> dict:
    fid, ru, _, _, _, subtypes, skills, scenarios = row
    level = LEVELS[(family_index + local_index) % 4]
    subtype = subtypes[(global_id + local_index) % len(subtypes)]
    context, action, outcome = scenarios[(global_id + local_index * 2) % len(scenarios)]
    required_idx = [(global_id + n * 2) % len(skills) for n in range(3)]
    preferred_idx = [(global_id + n * 2 + 1) % len(skills) for n in range(2)]
    required = [skills[n] for n in required_idx]
    preferred = [skills[n] for n in preferred_idx if skills[n] not in required]
    if len(preferred) < 2:
        preferred.append(skills[(required_idx[-1] + 1) % len(skills)])
    work_format = FORMATS[(global_id + local_index) % 3]
    city = None if work_format == "remote" else CITIES[(global_id * 2 + local_index) % len(CITIES)]
    salary_min = {"junior": 80000, "middle": 145000, "senior": 230000, "lead": 300000}[level]
    salary_max = salary_min + 25000 + global_id % 4 * 10000
    team = f"Синтетическая команда {local_index + 1:02d}-{global_id % 4 + 1:02d}"
    headline = ("устойчивый контур", "понятный рабочий путь", "проверяемое качество", "развитие платформы")[global_id % 4]
    responsibilities = [
        f"Уточнить границы рабочего сценария и собрать пример проблемы: {context}.",
        "Сравнить варианты решения, обозначить технические и пользовательские компромиссы.",
        "Согласовать с командой критерий проверки и порядок безопасного внедрения.",
        "Проверить результат на повторяемом сценарии и записать оставшиеся ограничения.",
    ]
    return {"vacancy_id": f"syn-vacancy-{global_id:03d}", "title": f"{LEVEL_LABELS[level]} {subtype} — {headline}",
        "role_family_id": fid, "role_family_name": ru, "subtype": subtype, "role_level": level,
        "description": f"{team} развивает направление «{subtype}». Команда разбирает задачу: {context}. Важно не только выбрать инструмент, но и заранее договориться, как проверить и поддерживать решение.",
        "team_context": f"{team}; вымышленная демонстрационная команда, не реальный работодатель.",
        "responsibilities": responsibilities,
        "illustrative_work_example": {"problem": context, "possible_approach": action, "target_state": outcome,
                                      "notice": "Полностью вымышленный пример задачи, не кейс реального работодателя."},
        "expected_results": [f"Для сценария «{context}» согласованы критерий результата и границы решения.",
                             "Выбранный подход можно повторить на контрольном сценарии; ограничения описаны.",
                             f"Иллюстративный сюжет примера: «{outcome}». Это не обещание эффекта или KPI."],
        "required_skills": [{"id": key, "label": label} for key, label in required],
        "preferred_skills": [{"id": key, "label": label} for key, label in preferred], "stack": list(dict.fromkeys(label for _, label in required + preferred)),
        "salary": {"min_rub_month_gross": salary_min, "max_rub_month_gross": salary_max, "basis": "synthetic_demo_range_not_market_data"},
        "work_format": work_format, "work_city": city,
        "first_30_days": f"В первые 30 дней изучить сценарий «{context}», договориться о критерии проверки и подготовить небольшой безопасный шаг.",
        "interview_stages": [{"name": "Задачи и ожидания", "duration_minutes": 30}, {"name": "Разбор практического решения", "duration_minutes": 50}, {"name": "Команда и вопросы кандидата", "duration_minutes": 25}],
        "take_home_minutes": (0, 45, 75)[global_id % 3], "response_sla_hours": 48,
        "publication_state": "active", "discoverable_demo": True,
        "employer": {"display_name": team, "contact": None, "is_real_employer": False},
        "data_mode": "synthetic", "origin": "synthetic_fixture", "assessment_required": False, "market_claim": False}

def digest(text: str) -> str:
    return hashlib.sha256(re.sub(r"\W+", " ", text.casefold(), flags=re.UNICODE).strip().encode()).hexdigest()

def validate(profiles: list[dict], vacancies: list[dict], taxonomy: list[dict]) -> dict:
    family_ids = {item["id"] for item in taxonomy}
    assert len(taxonomy) == 32 and len(family_ids) == 32
    assert len(profiles) == 200 and len(vacancies) == 120
    pc = Counter(p["target_roles"][0]["role_family_id"] for p in profiles)
    vc = Counter(v["role_family_id"] for v in vacancies)
    lc = Counter(p["target_roles"][0]["declared_level"] for p in profiles)
    role_levels = Counter(v["role_level"] for v in vacancies)
    cc = Counter(p["career_path"]["type"] for p in profiles)
    completeness = {tuple(p["section_status"].values()) for p in profiles}
    assert set(pc) == family_ids and min(pc.values()) >= 5
    assert set(vc) == family_ids and set(vc.values()) <= {3, 4}
    assert set(lc) == set(LEVELS) and min(lc.values()) >= 25
    assert set(role_levels) == set(LEVELS) and min(role_levels.values()) >= 25
    assert len(cc) >= 6 and len(completeness) >= 8
    assert len({p["profile_id"] for p in profiles}) == 200 and len({v["vacancy_id"] for v in vacancies}) == 120
    narrative_hashes = [digest(p["achievement_story"]["context"] + p["achievement_story"]["personal_contribution"] + p["achievement_story"]["outcome"]) for p in profiles]
    vacancy_hashes = [digest(v["title"] + v["description"]) for v in vacancies]
    assert len(set(narrative_hashes)) == 200, "candidate narratives must be distinct"
    assert len(set(vacancy_hashes)) == 120, "vacancy texts must be distinct"
    for profile in profiles:
        assert profile["data_mode"] == "synthetic" and profile["assessment_status"] == "not_assessed" and profile["contact"] is None
        metric = profile["achievement_story"].get("illustrative_metric")
        assert metric is None or (metric["source"] == "synthetic_fixture" and "не является реальным" in metric["notice"])
        salary = profile["salary_expectation_rub_month"]
        assert salary is None or salary["max"] >= salary["min"]
        for job in profile["work_history"]:
            start, end = job["period"]["from"], job["period"]["to"]
            assert date.fromisoformat(start + "-01") <= date.fromisoformat(end + "-01")
    for vacancy in vacancies:
        assert vacancy["role_family_id"] in family_ids and vacancy["role_level"] in LEVELS
        assert vacancy["publication_state"] == "active" and vacancy["discoverable_demo"] is True
        assert vacancy["data_mode"] == "synthetic" and vacancy["employer"]["contact"] is None
        assert vacancy["illustrative_work_example"]["notice"].startswith("Полностью вымышленный")
        assert vacancy["salary"]["max_rub_month_gross"] >= vacancy["salary"]["min_rub_month_gross"]
        assert vacancy["work_format"] == "remote" or vacancy["work_city"]
        assert len(vacancy["required_skills"]) >= 3 and len(vacancy["responsibilities"]) >= 4
    return {"data_version": "synthetic_it_market_v1", "seed": SEED, "profiles": 200, "vacancies": 120, "families": 32,
            "profiles_by_family": dict(sorted(pc.items())), "vacancies_by_family": dict(sorted(vc.items())),
            "profiles_by_declared_level": dict(sorted(lc.items())), "vacancies_by_level": dict(sorted(role_levels.items())),
            "career_paths": dict(sorted(cc.items())),
            "optional_section_patterns": len(completeness), "profiles_with_illustrative_metrics": sum(p["achievement_story"]["illustrative_metric"] is not None for p in profiles),
            "unique_candidate_narratives": len(set(narrative_hashes)),
            "unique_vacancy_texts": len(set(vacancy_hashes)), "status": "All candidate evidence is synthetic and not assessed."}

def write_jsonl(path: Path, records: list[dict]) -> None:
    path.write_text("".join(json.dumps(row, ensure_ascii=False, separators=(",", ":")) + "\n" for row in records), encoding="utf-8")

def write_csv(path: Path, records: list[dict], fields: list[str]) -> None:
    with path.open("w", encoding="utf-8-sig", newline="") as stream:
        writer = csv.DictWriter(stream, fieldnames=fields, extrasaction="ignore", lineterminator="\n")
        writer.writeheader()
        for record in records:
            writer.writerow({key: json.dumps(record[key], ensure_ascii=False) if isinstance(record.get(key), (dict, list)) else record.get(key) for key in fields})

def main() -> None:
    rng = random.Random(SEED)
    taxonomy = [family_json(row) for row in FAMILIES]
    profiles, vacancies = [], []
    candidate_id = vacancy_id = 1
    for family_index, row in enumerate(FAMILIES):
        for local_index in range(10 if family_index < 8 else 5):
            profiles.append(build_profile(candidate_id, row, local_index, rng))
            candidate_id += 1
        for local_index in range(4 if family_index < 24 else 3):
            vacancies.append(build_vacancy(vacancy_id, row, family_index, local_index))
            vacancy_id += 1
    report = validate(profiles, vacancies, taxonomy)
    ROOT.mkdir(parents=True, exist_ok=True)
    (ROOT / "taxonomy.json").write_text(json.dumps({"version": "it_roles_v1", "families": taxonomy}, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    write_jsonl(ROOT / "profiles.jsonl", profiles)
    write_jsonl(ROOT / "vacancies.jsonl", vacancies)
    write_csv(ROOT / "profiles.csv", profiles, ["profile_id", "display_name", "resume_title", "target_roles", "city", "preferred_work_formats", "salary_expectation_rub_month", "experience_months_declared", "career_path", "summary", "skills", "work_history", "projects", "education", "languages", "certificates", "achievement_story", "section_status", "assessment_status", "data_mode"])
    write_csv(ROOT / "vacancies.csv", vacancies, ["vacancy_id", "title", "role_family_id", "role_family_name", "subtype", "role_level", "description", "team_context", "illustrative_work_example", "responsibilities", "expected_results", "required_skills", "preferred_skills", "stack", "salary", "work_format", "work_city", "first_30_days", "interview_stages", "take_home_minutes", "response_sla_hours", "publication_state", "discoverable_demo", "employer", "data_mode"])
    (ROOT / "quality_report.json").write_text(json.dumps(report, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(json.dumps({"profiles": report["profiles"], "vacancies": report["vacancies"], "families": report["families"],
                      "profile_levels": report["profiles_by_declared_level"], "vacancy_levels": report["vacancies_by_level"], "unique_stories": report["unique_candidate_narratives"],
                      "unique_vacancies": report["unique_vacancy_texts"], "optional_section_patterns": report["optional_section_patterns"],
                      "profiles_with_illustrative_metrics": report["profiles_with_illustrative_metrics"]}, ensure_ascii=False))

if __name__ == "__main__":
    main()
